/* Card set: Bodies of Water (generated from water.csv by package_water.py).
   (water.js exceeds the push size limit, so the remaining cards live in water-additions.js,
   which must stay directly after 'water.js' in sets/manifest.js.) */
CardSets.register({"id":"water","name":"Bodies of Water","code":"WATER","description":"413 rivers, lakes, oceans, seas, bays, gulfs, sounds and straits — from the Nile and the Pacific to a 310-acre fishing lake in Tennessee. Real photos, each with a fact built to last.","theme":{"primary":"#07507e","secondary":"#3ec6dd","artBackground":"#06283d","artFit":"cover"},"pack":{"name":"Bodies of Water","emblem":"🌊","skin":"water"},"cards":[{"name":"Nile River","rarity":"chase","id":"nile-river","subtitle":"River","details":"Flows north for about 6,650 km through northeastern Africa to the Mediterranean; its White and Blue branches meet at Khartoum, Sudan.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4a/Beautiful_nature_along_Nile_River_01.jpg"},{"name":"Amazon River","rarity":"chase","id":"amazon-river","subtitle":"River","details":"The world's largest river by discharge, carrying more water into the Atlantic than the next seven largest rivers combined.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f8/Amazon_River_ESA387332.jpg"},{"name":"Mississippi River","rarity":"chase","id":"mississippi-river","subtitle":"River","details":"Runs from Lake Itasca in Minnesota to the Gulf of Mexico; with the Missouri, it forms one of the world's great river systems.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d2/Efmo_View_from_Fire_Point.jpg"},{"name":"Caspian Sea","rarity":"chase","id":"caspian-sea","subtitle":"Lake","details":"The world's largest lake by area at about 371,000 sq km, bordered by five countries and lying below sea level.","image":"https://upload.wikimedia.org/wikipedia/commons/9/98/Caspian_Sea_from_orbit.jpg"},{"name":"Lake Superior","rarity":"chase","id":"lake-superior","subtitle":"Lake","details":"Largest freshwater lake by surface area at 82,100 sq km; its volume could fill all the other Great Lakes combined.","image":"https://upload.wikimedia.org/wikipedia/commons/9/94/Lake_Superior%2C_ISS.jpg"},{"name":"Lake Baikal","rarity":"chase","id":"lake-baikal","subtitle":"Lake","details":"Earth's deepest lake at 1,642 m, holding about a fifth of the world's surface fresh water in Siberia.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6a/Baikal.A2001296.0420.250m-NASA.jpg"},{"name":"Pacific Ocean","rarity":"chase","id":"pacific-ocean","subtitle":"Ocean","details":"Covers about 165 million sq km - more than all Earth's land combined - and holds Challenger Deep, the planet's deepest point.","image":"https://upload.wikimedia.org/wikipedia/commons/4/40/P%C4%81hoehoe_lava_meets_Pacific.jpg"},{"name":"Atlantic Ocean","rarity":"chase","id":"atlantic-ocean","subtitle":"Ocean","details":"The second-largest ocean, split by the Mid-Atlantic Ridge and widening as the Americas drift from Europe and Africa.","image":"https://upload.wikimedia.org/wikipedia/commons/6/64/Gaztelugache%2C_Bermeo%2C_Pa%C3%ADs_Vasco%2C_Espa%C3%B1a%2C_2019-08-13%2C_DD_14.jpg"},{"name":"Indian Ocean","rarity":"chase","id":"indian-ocean","subtitle":"Ocean","details":"The third-largest ocean and the only one named after a country, washing Africa, Asia, Australia and Antarctica.","image":"https://upload.wikimedia.org/wikipedia/commons/3/32/Maldives_Resort%2C_Indian_Ocean.jpg"},{"name":"Mediterranean Sea","rarity":"chase","id":"mediterranean-sea","subtitle":"Sea","details":"Nearly landlocked between Europe, Africa and Asia, joined to the Atlantic only through the Strait of Gibraltar.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1c/Mediterranean_Sea_16.61811E_38.99124N.jpg"},{"name":"Yangtze River","rarity":"legendary","id":"yangtze-river","subtitle":"River","details":"Asia's longest river at 6,300 km; home to the Three Gorges Dam, the world's largest power station.","image":"https://upload.wikimedia.org/wikipedia/commons/5/58/Dusk_on_the_Yangtze_River.jpg"},{"name":"Missouri River","rarity":"legendary","id":"missouri-river","subtitle":"River","details":"Longest river in North America, flowing from Montana's Rockies across the Great Plains to join the Mississippi at St. Louis.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ea/Missouri_River_in_2021_01.jpg"},{"name":"Congo River","rarity":"legendary","id":"congo-river","subtitle":"River","details":"The world's deepest river, measured beyond 220 m; it drains the Congo rainforest, second in size only to the Amazon's.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cb/Aerial_view_of_the_Congo_River_near_Kisangani.jpg"},{"name":"Huang He (Yellow River)","rarity":"legendary","id":"huang-he-yellow-river","subtitle":"River","details":"China's second-longest river, tinted yellow by loess silt - the cradle where early Chinese civilization grew.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d4/Yellow_River_-_panoramio.jpg"},{"name":"Mekong River","rarity":"legendary","id":"mekong-river","subtitle":"River","details":"Southeast Asia's longest river, flowing from the Tibetan Plateau through six countries to a vast delta in Vietnam.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9f/Mekong-River-Near-Luang-Prabang.jpg"},{"name":"Danube River","rarity":"legendary","id":"danube-river","subtitle":"River","details":"Europe's second-longest river, flowing through ten countries from Germany's Black Forest to a Black Sea delta.","image":"https://upload.wikimedia.org/wikipedia/commons/5/53/View_from_Gell%C3%A9rt_Hill_to_the_Danube%2C_Hungary_-_Budapest_%2828493220635%29.jpg"},{"name":"Volga River","rarity":"legendary","id":"volga-river","subtitle":"River","details":"Europe's longest river at 3,530 km, flowing entirely within Russia southward to the Caspian Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f0/Yaroslavl._Volga_River._Cathedral_of_the_Dormition_P5212700_2200.jpg"},{"name":"Ganges River","rarity":"legendary","id":"ganges-river","subtitle":"River","details":"Sacred to Hindus, flowing 2,525 km from the Himalayas across northern India and Bangladesh to the Bay of Bengal.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b9/Varanasiganga.jpg"},{"name":"Lake Victoria","rarity":"legendary","id":"lake-victoria","subtitle":"Lake","details":"Africa's largest lake and the world's second-largest freshwater lake by area, shared by Uganda, Kenya and Tanzania.","image":"https://upload.wikimedia.org/wikipedia/commons/7/74/ISS042-E-263206_-_View_of_Earth.jpg"},{"name":"Lake Huron","rarity":"legendary","id":"lake-huron","subtitle":"Lake","details":"Second-largest Great Lake by area, home to Manitoulin Island, the world's largest freshwater island.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ad/Lake_Huron_in_winter.jpg"},{"name":"Lake Michigan","rarity":"legendary","id":"lake-michigan","subtitle":"Lake","details":"The only Great Lake lying entirely within the United States, bordered by Michigan, Wisconsin, Illinois and Indiana.","image":"https://upload.wikimedia.org/wikipedia/commons/1/13/Lake_Michigan_in_true_color.jpg"},{"name":"Lake Tanganyika","rarity":"legendary","id":"lake-tanganyika","subtitle":"Lake","details":"The world's longest freshwater lake at 673 km and its second deepest, shared by Tanzania, DR Congo, Burundi and Zambia.","image":"https://upload.wikimedia.org/wikipedia/commons/4/46/STS51G-034-0012_Lake_Tanganyika_June1985.jpg"},{"name":"Lake Erie","rarity":"legendary","id":"lake-erie","subtitle":"Lake","details":"The shallowest and warmest Great Lake, averaging just 19 m deep, and the southernmost of the five.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3b/A1.23188.1851.LakeErie.143.250m.jpg"},{"name":"Lake Ontario","rarity":"legendary","id":"lake-ontario","subtitle":"Lake","details":"The smallest Great Lake by area; fed by the Niagara River below the falls, it drains into the St. Lawrence River.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7a/ISS-36_Lake_Ontario_%28horizontal%29.jpg"},{"name":"Arctic Ocean","rarity":"legendary","id":"arctic-ocean","subtitle":"Ocean","details":"The smallest and shallowest of the five oceans, centred on the North Pole and ringed by North America and Eurasia.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3d/Iceberg_in_the_Arctic_with_its_underside_exposed.jpg"},{"name":"Southern Ocean","rarity":"legendary","id":"southern-ocean","subtitle":"Ocean","details":"Encircles Antarctica in an unbroken ring, powered by the Antarctic Circumpolar Current, the world's largest ocean current.","image":"https://upload.wikimedia.org/wikipedia/commons/c/ca/South_Shetland-2016-Southern_Ocean_%28off_Elephant_Island%29%E2%80%93Iceberg_01.jpg"},{"name":"Caribbean Sea","rarity":"legendary","id":"caribbean-sea","subtitle":"Sea","details":"A tropical western Atlantic sea whose western shore holds the Mesoamerican Barrier Reef, among the world's largest reef systems.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6f/Brooding_Caribbean_Sunrise_5707.jpg"},{"name":"South China Sea","rarity":"legendary","id":"south-china-sea","subtitle":"Sea","details":"A Pacific marginal sea on a major world trade route, bordered by China, Vietnam, Malaysia, Brunei and the Philippines.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c3/Mar_de_China_Meridional_-_BM_WMS_2004.jpg"},{"name":"Philippine Sea","rarity":"legendary","id":"philippine-sea","subtitle":"Sea","details":"The world's largest sea at about 5.7 million sq km, lying over the Philippine Sea Plate east of the Philippine archipelago.","image":"https://upload.wikimedia.org/wikipedia/commons/3/35/Cloudscape_Over_the_Philippine_Sea.jpg"},{"name":"Arabian Sea","rarity":"legendary","id":"arabian-sea","subtitle":"Sea","details":"The northwestern arm of the Indian Ocean, between India and the Arabian Peninsula, long sailed on seasonal monsoon winds.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b5/Arabian_Sea_and_Morjim_Beach_as_seen_from_Vagator_Fort%2C_Goa%2C_India.jpg"},{"name":"Bering Sea","rarity":"legendary","id":"bering-sea","subtitle":"Sea","details":"A cold North Pacific sea between Alaska and Russia, joined to the Arctic Ocean by the narrow Bering Strait.","image":"https://upload.wikimedia.org/wikipedia/commons/4/46/Bering_Sea_sunset_-_NOAA.jpg"},{"name":"Coral Sea","rarity":"legendary","id":"coral-sea","subtitle":"Sea","details":"The world's second-largest sea, off northeastern Australia, holding the Great Barrier Reef, the largest coral reef system.","image":"https://upload.wikimedia.org/wikipedia/commons/5/52/Sunset_in_the_Coral_Sea.jpg"},{"name":"Bay of Bengal","rarity":"legendary","id":"bay-of-bengal","subtitle":"Bay","details":"The world's largest bay, fed by the Ganges, Brahmaputra and Meghna rivers, whose combined delta is Earth's largest.","image":"https://upload.wikimedia.org/wikipedia/commons/6/62/Bay_of_Bengal_Sunrise_at_Nagapattinam_Beach.jpg"},{"name":"Gulf of Mexico","rarity":"legendary","id":"gulf-of-mexico","subtitle":"Gulf","details":"Bordered by the U.S., Mexico and Cuba; the Mississippi empties here and its warm Loop Current feeds the Gulf Stream.","image":"https://upload.wikimedia.org/wikipedia/commons/1/12/Cumulonimbus_calvus_cloud_over_the_Gulf_of_Mexico_in_Galveston%2C_Texas.jpg"},{"name":"Strait of Gibraltar","rarity":"legendary","id":"strait-of-gibraltar","subtitle":"Strait","details":"Only 13 km wide at its narrowest, the sole natural link between the Mediterranean Sea and the Atlantic Ocean.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e8/STS059-238-074_Strait_of_Gibraltar.jpg"},{"name":"Strait of Malacca","rarity":"legendary","id":"strait-of-malacca","subtitle":"Strait","details":"The busiest shipping strait, linking the Indian and Pacific Oceans between Malaysia, Indonesia and Singapore.","image":"https://upload.wikimedia.org/wikipedia/commons/3/32/Ships_in_the_Malacca_Strait.jpg"},{"name":"Strait of Hormuz","rarity":"legendary","id":"strait-of-hormuz","subtitle":"Strait","details":"The only sea outlet from the Persian Gulf to the open ocean, a narrow chokepoint for tankers from Gulf oil ports.","image":"https://upload.wikimedia.org/wikipedia/commons/1/16/Strait_of_Hormuz_and_Musandam_Peninsula_%28MODIS_2018-12-10%29.jpg"},{"name":"Paraná River","rarity":"epic","id":"parana-river","subtitle":"River","details":"South America's second-longest river at 4,880 km, flowing through Brazil, Paraguay and Argentina before forming the Río de la Plata.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c8/Confluence_of_the_Iguazu_and_Parana_rivers%2C_Puerto_Iguazu%2C_Misiones%2C_Argentina%2C_6th._Jan._2011_-_Flickr_-_PhillipC.jpg"},{"name":"Yenisei River","rarity":"epic","id":"yenisei-river","subtitle":"River","details":"The great Siberian river system: 5,539 km from Mongolia to the Kara Sea, carrying more water to the Arctic Ocean than any other river.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f6/%D0%A1%D0%BB%D0%B8%D1%8F%D0%BD%D0%B8%D0%B5_%D1%80%D0%B5%D0%BA_%D0%95%D0%BD%D0%B8%D1%81%D0%B5%D0%B9.jpg"},{"name":"Ob River","rarity":"epic","id":"ob-river","subtitle":"River","details":"With its Irtysh tributary it runs 5,410 km across western Siberia, draining a basin of nearly 3 million km² — among Earth's largest.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3e/March_evening._The_sun_fell_across_the_Ob_river.jpg"},{"name":"Lena River","rarity":"epic","id":"lena-river","subtitle":"River","details":"Runs 4,400 km wholly within Russia to the Laptev Sea, where it spreads into the Arctic's largest delta, nearly 30,000 km² of tundra channels.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c3/Lone-maiden-formation.jpg"},{"name":"Amur River","rarity":"epic","id":"amur-river","subtitle":"River","details":"The Amur–Argun system runs 4,444 km along much of the Russia–China border before emptying into the Sea of Okhotsk.","image":"https://upload.wikimedia.org/wikipedia/commons/5/52/Amur_River.JPG"},{"name":"Indus River","rarity":"epic","id":"indus-river","subtitle":"River","details":"The river that gave India its name — from Persian Hindu via Greek Indos — flows from the Tibetan Plateau through Pakistan to the Arabian Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7f/Nanga_Parbat_Indus_Gorge.jpg"},{"name":"Brahmaputra River","rarity":"epic","id":"brahmaputra-river","subtitle":"River","details":"Begins as the Yarlung Tsangpo in Tibet, slices through the Himalayas in a vast gorge, then joins the Ganges delta in Bangladesh.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9c/Yarlong_Tsangpo.jpg"},{"name":"Colorado River","rarity":"epic","id":"colorado-river","subtitle":"River","details":"Carver of the Grand Canyon: it flows 2,330 km from the Colorado Rockies through the desert Southwest to the Gulf of California.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b9/Horseshoe_Bend_13_February_2023.jpg"},{"name":"Columbia River","rarity":"epic","id":"columbia-river","subtitle":"River","details":"Flows 2,000 km from British Columbia to the Pacific, forming much of the Oregon–Washington border and powering a chain of great hydro dams.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Columbia_River_from_Rowena_Crest_Viewpoint_looking_east.jpg"},{"name":"Mackenzie River","rarity":"epic","id":"mackenzie-river","subtitle":"River","details":"Canada's longest river system at 4,241 km including the Peace and Finlay, flowing from Great Slave Lake north to the Beaufort Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a3/Mackenzie_from-east.jpg"},{"name":"Rhine River","rarity":"epic","id":"rhine-river","subtitle":"River","details":"Flows about 1,230 km from the Swiss Alps past Cologne and Rotterdam to the North Sea — one of Europe's great commercial waterways.","image":"https://upload.wikimedia.org/wikipedia/commons/6/67/Middle_Bridge%2C_Basel%2C_Switzerland.JPG"},{"name":"Yukon River","rarity":"epic","id":"yukon-river","subtitle":"River","details":"Flows 3,190 km from British Columbia across Alaska to the Bering Sea; its tributary, the Klondike, sparked an 1890s gold rush.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4f/Canoeing_the_Yukon_River.jpg"},{"name":"Rio Grande","rarity":"epic","id":"rio-grande","subtitle":"River","details":"Flows 3,051 km from Colorado's San Juan Mountains to the Gulf of Mexico, forming a long stretch of the U.S.–Mexico border.","image":"https://upload.wikimedia.org/wikipedia/commons/3/32/Rio_Grande_in_Big_Bend_NP.jpg"},{"name":"Great Slave Lake","rarity":"epic","id":"great-slave-lake","subtitle":"Lake","details":"North America's deepest lake at 614 m, gouged by glaciers in Canada's Northwest Territories and drained by the Mackenzie River.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3b/Great_Slave_Lake_beach_in_Hay_River_1.jpg"},{"name":"Lake Malawi","rarity":"epic","id":"lake-malawi","subtitle":"Lake","details":"The 'calendar lake' — roughly 365 miles long and 52 wide — holds more fish species than any other lake, most of them cichlids.","image":"https://upload.wikimedia.org/wikipedia/commons/0/05/Lake_Malawi_seen_from_orbit.jpg"},{"name":"Lake Titicaca","rarity":"epic","id":"lake-titicaca","subtitle":"Lake","details":"At 3,812 m in the Andes on the Peru–Bolivia border, the highest lake in the world navigated by commercial vessels; it covers 8,372 km².","image":"https://upload.wikimedia.org/wikipedia/commons/7/73/Lake_Titicaca_ESA22522896.jpeg"},{"name":"Lake Ladoga","rarity":"epic","id":"lake-ladoga","subtitle":"Lake","details":"Europe's largest lake at about 17,700 km² near St. Petersburg, draining via the Neva River and dotted with some 660 islands.","image":"https://upload.wikimedia.org/wikipedia/commons/d/db/Sortavalan_saaristoa.jpg"},{"name":"Lake Winnipeg","rarity":"epic","id":"lake-winnipeg","subtitle":"Lake","details":"A vast, shallow remnant of glacial Lake Agassiz covering about 24,500 km² in Manitoba, drained north by the Nelson River to Hudson Bay.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c8/Commercial_fishing_on_Lake_Winnipeg%2C_Norway_House_Cree_Nation_%287461040808%29.jpg"},{"name":"Lake Balkhash","rarity":"epic","id":"lake-balkhash","subtitle":"Lake","details":"A lake of two personalities: its west half is fresh, fed by the Ili River, while its east half is salty — and it has no outflow.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0c/STS039-085-00E_Lake_Balkhash%2C_Kazakhstan_April_1991.jpg"},{"name":"Great Salt Lake","rarity":"epic","id":"great-salt-lake","subtitle":"Lake","details":"The largest salt lake in the Americas, in northern Utah; its brine can be far saltier than the ocean, supporting brine shrimp, not fish.","image":"https://upload.wikimedia.org/wikipedia/commons/3/37/Great_Salt_Lake_by_Sentinel-2.jpg"},{"name":"Lake Tahoe","rarity":"epic","id":"lake-tahoe","subtitle":"Lake","details":"Famed for its clarity, this Sierra Nevada lake is 501 m deep — the second-deepest in the United States after Oregon's Crater Lake.","image":"https://upload.wikimedia.org/wikipedia/commons/d/da/Tahoe_North_Shore_from_the_East_Shore.jpg"},{"name":"Great Bear Lake","rarity":"epic","id":"great-bear-lake","subtitle":"Lake","details":"The largest lake entirely in Canada at 31,153 km², sitting on the Arctic Circle in the Northwest Territories, icebound much of the year.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7c/Great_Bear_Lake_%28158842785%29.jpg"},{"name":"Dead Sea","rarity":"epic","id":"dead-sea","subtitle":"Lake","details":"Its shore is the lowest land on Earth, over 400 m below sea level, and its water is roughly ten times saltier than the ocean's.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6f/Dead_Sea_beach_00.JPG"},{"name":"Lake Volta","rarity":"epic","id":"lake-volta","subtitle":"Lake","details":"A reservoir in Ghana and the world's largest by surface area at about 8,500 km², formed by damming the Volta River at Akosombo.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bd/Adomi-bridge_0418.png"},{"name":"Lake Kariba","rarity":"epic","id":"lake-kariba","subtitle":"Lake","details":"A reservoir on the Zambezi between Zambia and Zimbabwe — the world's largest by volume, holding some 180 km³ of water.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a1/Lake_Kariba.jpg"},{"name":"Red Sea","rarity":"epic","id":"red-sea","subtitle":"Sea","details":"A rift sea where Africa and Arabia are pulling apart: about 2,250 km long, warm, salty and lined with rich coral reefs.","image":"https://upload.wikimedia.org/wikipedia/commons/1/16/Nuweiba%2C_Mountains%2C_Red_Sea%2C_Sinai%2C_Egypt.jpg"},{"name":"North Sea","rarity":"epic","id":"north-sea","subtitle":"Sea","details":"A shallow shelf sea between Britain and mainland Europe: it covers about 575,000 km² yet averages only around 95 m deep.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ae/NASA_NorthSea1_2.jpg"},{"name":"Baltic Sea","rarity":"epic","id":"baltic-sea","subtitle":"Sea","details":"One of the world's largest brackish seas — nearly enclosed and fed by big rivers, so its water is far less salty than the open ocean.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ed/Baltic_Sea_view_from_Schmiedeberg_hill_in_Rerik%2C_2025-06-23.jpg"},{"name":"Black Sea","rarity":"epic","id":"black-sea","subtitle":"Sea","details":"Below about 200 m its deep water holds no oxygen — a stagnant layer that preserves ancient wooden shipwrecks on the seabed.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0d/The_Danube_Spills_into_the_Black_Sea.jpg"},{"name":"Sea of Okhotsk","rarity":"epic","id":"sea-of-okhotsk","subtitle":"Sea","details":"A northwest Pacific sea walled in by Kamchatka, Sakhalin and the Kuril Islands; sea ice covers much of it in winter.","image":"https://upload.wikimedia.org/wikipedia/commons/8/82/Sea_of_Ochotsk_151.75790E_53.57880N.jpg"},{"name":"East China Sea","rarity":"epic","id":"east-china-sea","subtitle":"Sea","details":"A shallow marginal sea between China, Korea and the Ryukyu Islands, where the Yangtze River empties into the Pacific.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e8/Dayu_Bay_-_Damen_Shan_-_P1210677.JPG"},{"name":"Sea of Japan","rarity":"epic","id":"sea-of-japan","subtitle":"Sea","details":"Almost enclosed by Japan, Korea and Russia and joined to other seas by narrow straits, yet it plunges more than 3,700 m deep.","image":"https://upload.wikimedia.org/wikipedia/commons/6/63/Full-orbed_sunrise_over_East_Sea_in_South_Korea.JPG"},{"name":"Bay of Biscay","rarity":"epic","id":"bay-of-biscay","subtitle":"Bay","details":"Famed for violent winter storms off the coasts of France and Spain, and for deep water — over 4,700 m in its abyssal plain.","image":"https://upload.wikimedia.org/wikipedia/commons/8/86/Praia_de_Bares_4IX2015.jpg"},{"name":"Hudson Bay","rarity":"epic","id":"hudson-bay","subtitle":"Bay","details":"The world's second-largest bay at 1,230,000 km², after the Bay of Bengal — a shallow inland sea in northeastern Canada.","image":"https://upload.wikimedia.org/wikipedia/commons/8/86/Hudson_Bay_2008-07-21_by_Aqua.jpg"},{"name":"Gulf of Alaska","rarity":"epic","id":"gulf-of-alaska","subtitle":"Gulf","details":"The North Pacific's wide Alaskan curve: its shores hold Prince William Sound and Glacier Bay, where glaciers meet the sea.","image":"https://upload.wikimedia.org/wikipedia/commons/8/89/GulfOfAlaska_AMO_2008073.jpg"},{"name":"Gulf of California","rarity":"epic","id":"gulf-of-california","subtitle":"Gulf","details":"Jacques Cousteau called it 'the world's aquarium' — a narrow sea between Baja California and mainland Mexico with 900-plus fish species.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b0/The_Gulf_of_California_separates_mainland_Mexico_from_the_Baja_California_Peninsula_%28iss073e0865795%29.jpg"},{"name":"Persian Gulf","rarity":"epic","id":"persian-gulf","subtitle":"Gulf","details":"A shallow, warm gulf between Iran and the Arabian Peninsula, averaging only about 50 m deep, linked to the Arabian Sea by Hormuz.","image":"https://upload.wikimedia.org/wikipedia/commons/b/be/PersianGulf_vue_satellite_du_golfe_persique.jpg"},{"name":"Bosphorus","rarity":"epic","id":"bosphorus","subtitle":"Strait","details":"A 30 km strait through Istanbul joining the Black Sea to the Sea of Marmara — with Europe on one bank and Asia on the other.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Bosphorus_from_the_boat_1.jpg"},{"name":"Bering Strait","rarity":"epic","id":"bering-strait","subtitle":"Strait","details":"Only 82 km wide between Russia and Alaska; midway sit the Diomede Islands, one Russian, one American, split by the Date Line.","image":"https://upload.wikimedia.org/wikipedia/commons/1/16/Bering_Strait.jpeg"},{"name":"Strait of Magellan","rarity":"epic","id":"strait-of-magellan","subtitle":"Strait","details":"A 570 km natural passage through southern Chile linking the Atlantic and Pacific — the main sea route between them before the Panama Canal.","image":"https://upload.wikimedia.org/wikipedia/commons/0/05/StraitOfMagellan.jpg"},{"name":"English Channel","rarity":"epic","id":"english-channel","subtitle":"Channel","details":"A 560 km arm of the Atlantic between England and France, pinching to about 34 km at Dover — among the world's busiest shipping lanes.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7a/English_Channel_Satellite.jpg"},{"name":"Euphrates River","rarity":"rare","id":"euphrates-river","subtitle":"River","details":"Long river of Mesopotamia that joins the Tigris to form the Shatt al-Arab; its valley nurtured some of the earliest farming cities.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a3/The_Euphrates_River_in_Turkey%2C_Rumkale_%2852031477798%29.jpg"},{"name":"Tigris River","rarity":"rare","id":"tigris-river","subtitle":"River","details":"Flows past Mosul and Baghdad before joining the Euphrates in southern Iraq to form the Shatt al-Arab, on the way to the Persian Gulf.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6d/Mosul_river.jpg"},{"name":"Irrawaddy River","rarity":"rare","id":"irrawaddy-river","subtitle":"River","details":"Myanmar's main river, formed by the Mali and N'mai rivers in the north and flowing about 2,170 km south to the Andaman Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/8/87/Irrawaddy-River-Myanmar-Burma-2005.jpg"},{"name":"Zambezi River","rarity":"rare","id":"zambezi-river","subtitle":"River","details":"African river that plunges over Victoria Falls, the world's largest sheet of falling water, on its way to the Mozambique Channel.","image":"https://upload.wikimedia.org/wikipedia/commons/b/be/Zambezi_River_at_junction_of_Namibia%2C_Zambia%2C_Zimbabwe_%26_Botswana.jpg"},{"name":"Niger River","rarity":"rare","id":"niger-river","subtitle":"River","details":"West African river that arcs northeast into Mali, then bends southeast across Niger and Nigeria to a vast delta on the Atlantic.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c3/Niger%2C_Niamey%2C_Pont_Kennedy_%281%29.jpg"},{"name":"Orange River","rarity":"rare","id":"orange-river","subtitle":"River","details":"South Africa's longest river, rising in Lesotho and flowing about 2,200 km west to the Atlantic, forming part of Namibia's border.","image":"https://upload.wikimedia.org/wikipedia/commons/9/97/OrangeRiverUpington.jpg"},{"name":"Murray River","rarity":"rare","id":"murray-river","subtitle":"River","details":"Australia's longest river, flowing 2,508 km from the Australian Alps to the Southern Ocean, meeting the Darling along the way.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4d/Murray_River_Southbound_towards_Wellington_%40_Mannum_20250520-103223.jpg"},{"name":"Arkansas River","rarity":"rare","id":"arkansas-river","subtitle":"River","details":"Major Mississippi tributary that flows about 2,364 km from the Colorado Rockies across Kansas and Oklahoma to Arkansas.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6b/Arkansas_River_%282020%29.jpg"},{"name":"Ohio River","rarity":"rare","id":"ohio-river","subtitle":"River","details":"Formed at Pittsburgh where the Allegheny and Monongahela meet, then flows 1,579 km to join the Mississippi at Cairo, Illinois.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2f/Ohio_River_and_Cincinnati_from_Taylor%E2%80%93Southgate_Bridge.jpg"},{"name":"St. Lawrence River","rarity":"rare","id":"st-lawrence-river","subtitle":"River","details":"Connects the Great Lakes to the Atlantic Ocean, draining their waters past Montreal and Quebec City along the Canada-U.S. border.","image":"https://upload.wikimedia.org/wikipedia/commons/b/ba/Le_fleuve_Saint-Laurent.jpg"},{"name":"Hudson River","rarity":"rare","id":"hudson-river","subtitle":"River","details":"Flows 507 km from the Adirondack Mountains to New York Harbor; its lower half is a tidal estuary as far north as Troy.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c9/Hudson_river_from_bear_mountain_bridge.jpg"},{"name":"Seine River","rarity":"rare","id":"seine-river","subtitle":"River","details":"Flows about 777 km through Paris and on to the English Channel at Le Havre, crossed in the capital by dozens of bridges.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ed/Bercy%2C_Paris_01.jpg"},{"name":"River Thames","rarity":"rare","id":"river-thames","subtitle":"River","details":"Flows 346 km through London to the North Sea; below Teddington its waters rise and fall with the tide twice a day.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6e/London_Thames_Sunset_panorama_-_Feb_2008.jpg"},{"name":"Orinoco River","rarity":"rare","id":"orinoco-river","subtitle":"River","details":"Venezuelan river linked to the Amazon system by the Casiquiare channel, a natural waterway joining it to the Rio Negro.","image":"https://upload.wikimedia.org/wikipedia/commons/0/06/Orinoco_Bridge.jpg"},{"name":"Tocantins River","rarity":"rare","id":"tocantins-river","subtitle":"River","details":"Brazilian river flowing north about 2,450 km to join the Para River near the Amazon mouth, fed by the long Araguaia.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e8/Flavio_Andre_PonteFernandoHenriqueCardoso_Palmas_TO.jpg"},{"name":"São Francisco River","rarity":"rare","id":"sao-francisco-river","subtitle":"River","details":"Brazil's great northeastern river, flowing about 2,863 km north, then east to the Atlantic, watering a dry interior region.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6f/Canind%C3%A9_de_S%C3%A3o_Francisco-002.jpg"},{"name":"Salween River","rarity":"rare","id":"salween-river","subtitle":"River","details":"One of Asia's longest free-flowing rivers, running from the Tibetan Plateau through Myanmar and Thailand to the Andaman Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/1/16/Sweet_View_of_Salween_River_in_Tang_Yan_Township%2C_Shan_State%2C_Myanmar.jpg"},{"name":"Pearl River","rarity":"rare","id":"pearl-river","subtitle":"River","details":"China's Pearl River reaches the South China Sea in a vast delta shared by Guangzhou, Hong Kong, Macau and Shenzhen.","image":"https://upload.wikimedia.org/wikipedia/commons/8/83/Humen_Bridge-1.jpg"},{"name":"Saskatchewan River","rarity":"rare","id":"saskatchewan-river","subtitle":"River","details":"Formed where the North and South Saskatchewan rivers meet, then flows east across the prairies to Lake Winnipeg in Manitoba.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7a/2009-0519-CDNtrip-005-GrandRapidsMB.jpg"},{"name":"Fraser River","rarity":"rare","id":"fraser-river","subtitle":"River","details":"British Columbia's longest river, flowing 1,375 km to the Pacific near Vancouver and famous for its salmon runs.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9b/FraserRiver.jpg"},{"name":"Snake River","rarity":"rare","id":"snake-river","subtitle":"River","details":"Largest tributary of the Columbia River, flowing about 1,735 km across Idaho and carving Hells Canyon along the Oregon border.","image":"https://upload.wikimedia.org/wikipedia/commons/2/21/Adams_The_Tetons_and_the_Snake_River.jpg"},{"name":"Loire River","rarity":"rare","id":"loire-river","subtitle":"River","details":"France's longest river at about 1,006 km, flowing past a valley famed for its chateaux on the way to the Atlantic.","image":"https://upload.wikimedia.org/wikipedia/commons/1/14/La_Loire_%C3%A0_La_Bohalle_par_Cramos.JPG"},{"name":"Dnieper River","rarity":"rare","id":"dnieper-river","subtitle":"River","details":"Flows through Kyiv and across Ukraine for about 2,200 km from Russia and Belarus to the Black Sea near Kherson.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4f/Dniepr_river_in_Kyiv.jpg"},{"name":"Elbe River","rarity":"rare","id":"elbe-river","subtitle":"River","details":"Rises in the Czech Republic and flows about 1,094 km through Dresden and Hamburg to the North Sea at Cuxhaven.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0c/Labe_udoli.jpg"},{"name":"Lake Onega","rarity":"rare","id":"lake-onega","subtitle":"Lake","details":"Europe's second-largest lake after Ladoga, in northwest Russia; it drains north through the Onega River to the White Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/9/96/Lake_Onega%2C_lighthouse_P7110300_2200.jpg"},{"name":"Lake Nicaragua","rarity":"rare","id":"lake-nicaragua","subtitle":"Lake","details":"Central America's largest lake; bull sharks once swam up the San Juan River from the Caribbean and were mistaken for a unique freshwater species.","image":"https://upload.wikimedia.org/wikipedia/commons/9/99/Lake_Nicaragua.jpg"},{"name":"Lake Athabasca","rarity":"rare","id":"lake-athabasca","subtitle":"Lake","details":"Straddles Alberta and Saskatchewan; its western end meets the Peace-Athabasca Delta, one of the world's great inland deltas.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9c/Lake_Athabasca%2C_Canada.jpg"},{"name":"Lake Turkana","rarity":"rare","id":"lake-turkana","subtitle":"Lake","details":"The world's largest permanent desert lake and largest alkaline lake, a jade-green sea in Kenya's arid Rift Valley.","image":"https://upload.wikimedia.org/wikipedia/commons/8/84/Lake_turkana.jpg"},{"name":"Lake Chad","rarity":"rare","id":"lake-chad","subtitle":"Lake","details":"Shallow lake shared by Chad, Niger, Nigeria and Cameroon that shrank dramatically from the 1960s as rains and irrigation demands shifted.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a9/Lake_Chad_%28MODIS_2018-06-07%29.jpg"},{"name":"Lake Toba","rarity":"rare","id":"lake-toba","subtitle":"Lake","details":"The world's largest volcanic lake, filling the caldera left by a supervolcano eruption about 74,000 years ago in Sumatra.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c4/Lake_Toba_and_the_surrounding_hills.jpg"},{"name":"Lake Van","rarity":"rare","id":"lake-van","subtitle":"Lake","details":"Turkiye's largest lake and the world's largest soda lake; its salty, alkaline waters have no outlet to the sea.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6f/STS079-781-53.jpg"},{"name":"Lake Como","rarity":"rare","id":"lake-como","subtitle":"Lake","details":"Deep glacial lake in the Italian Alps shaped like an upside-down Y, its three arms meeting near the town of Bellagio.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cc/Sentiero_del_Viandante_DSC_6340_%2814020554463%29.jpg"},{"name":"Lake Geneva","rarity":"rare","id":"lake-geneva","subtitle":"Lake","details":"Crescent-shaped lake on the Swiss-French border; the Rhone enters at its eastern end and flows out at Geneva in the west.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1b/Lake_Geneva_by_Sentinel-2.jpg"},{"name":"Crater Lake","rarity":"rare","id":"crater-lake","subtitle":"Lake","details":"The deepest lake in the United States at 1,943 feet, filling Mount Mazama's caldera with intensely blue, river-free water.","image":"https://upload.wikimedia.org/wikipedia/commons/5/51/Crater_Lake_National_Park_%282023%29.jpg"},{"name":"Loch Ness","rarity":"rare","id":"loch-ness","subtitle":"Lake","details":"Scottish loch holding more fresh water than all the lakes of England and Wales combined - and home to the Nessie legend.","image":"https://upload.wikimedia.org/wikipedia/commons/5/51/LochNessUrquhart.jpg"},{"name":"Lake Taupo","rarity":"rare","id":"lake-taupo","subtitle":"Lake","details":"New Zealand's largest lake by area, filling the caldera of Taupo Volcano, site of one of Earth's great prehistoric eruptions.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3d/Lake_Taupo.jpg"},{"name":"Lake Issyk-Kul","rarity":"rare","id":"lake-issyk-kul","subtitle":"Lake","details":"Its name means 'warm lake': ringed by snow-capped Tian Shan peaks, this saline Kyrgyz lake never freezes.","image":"https://upload.wikimedia.org/wikipedia/commons/7/79/Issykkul_plyag.jpg"},{"name":"Lake Qinghai","rarity":"rare","id":"lake-qinghai","subtitle":"Lake","details":"China's largest lake, an alkaline salt lake high on the Tibetan Plateau that gave Qinghai Province its name.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6f/Qinghai_lake.jpg"},{"name":"Lake Mead","rarity":"rare","id":"lake-mead","subtitle":"Lake","details":"The largest U.S. reservoir by capacity when full, formed by Hoover Dam on the Colorado River east of Las Vegas.","image":"https://upload.wikimedia.org/wikipedia/commons/0/02/Lake_Mead_in_July_2022_by_Landsat.jpg"},{"name":"Lake Powell","rarity":"rare","id":"lake-powell","subtitle":"Lake","details":"Colorado River reservoir behind Glen Canyon Dam, flooding red-rock canyons along the Utah-Arizona border.","image":"https://upload.wikimedia.org/wikipedia/commons/2/21/Lake_Powell_by_Sentinel-2.jpg"},{"name":"Yellow Sea","rarity":"rare","id":"yellow-sea","subtitle":"Sea","details":"Shallow sea between China and Korea, tinted by yellow silt carried down by rivers including the Yellow River.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0e/The_Yellow_Sea_%28crop%29_%2816639035116%29.jpg"},{"name":"Tasman Sea","rarity":"rare","id":"tasman-sea","subtitle":"Sea","details":"Sea between Australia and New Zealand, about 2,000 km across and named for Dutch explorer Abel Tasman.","image":"https://upload.wikimedia.org/wikipedia/commons/9/97/Tasman_Sea_Greymouth_%2831581729291%29.jpg"},{"name":"Norwegian Sea","rarity":"rare","id":"norwegian-sea","subtitle":"Sea","details":"Marginal sea of the North Atlantic between Norway, Iceland and Svalbard, open to the Greenland and Barents seas.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f4/V%C3%A5gakaillen_nattlys.JPG"},{"name":"Barents Sea","rarity":"rare","id":"barents-sea","subtitle":"Sea","details":"Shallow Arctic shelf sea north of Norway and Russia, named for Dutch navigator Willem Barentsz.","image":"https://upload.wikimedia.org/wikipedia/commons/0/02/Nordkapp_landscape_Barents_Sea.jpg"},{"name":"Andaman Sea","rarity":"rare","id":"andaman-sea","subtitle":"Sea","details":"Northeastern arm of the Indian Ocean between Myanmar and Thailand and India's Andaman and Nicobar Islands.","image":"https://upload.wikimedia.org/wikipedia/commons/3/32/Andaman_Sea%2C_Andaman_Islands.jpg"},{"name":"Labrador Sea","rarity":"rare","id":"labrador-sea","subtitle":"Sea","details":"Arm of the North Atlantic between Greenland and Labrador, a key site where cold, dense ocean water forms and sinks.","image":"https://upload.wikimedia.org/wikipedia/commons/7/70/Labrador-sea-paamiut.jpg"},{"name":"Banda Sea","rarity":"rare","id":"banda-sea","subtitle":"Sea","details":"Deep Indonesian sea ringed by the Maluku Islands, including the Banda Islands once prized for their nutmeg.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fb/Run_and_Nailaka_%28Banda_Islands%29.jpg"},{"name":"Scotia Sea","rarity":"rare","id":"scotia-sea","subtitle":"Sea","details":"Sea between the Antarctic Peninsula, South Georgia and Tierra del Fuego, opening west into the Drake Passage.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8b/Scotia_Sea_1996.jpg"},{"name":"Irish Sea","rarity":"rare","id":"irish-sea","subtitle":"Sea","details":"Sea between Ireland and Great Britain, joining the Atlantic through St George's Channel and the North Channel.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e1/Irish_Sea_satellite_image.jpg"},{"name":"Chesapeake Bay","rarity":"rare","id":"chesapeake-bay","subtitle":"Bay","details":"The largest estuary in the United States, about 200 miles long, fed by rivers draining parts of six states and Washington, D.C.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e6/Chesapeakelandsat.jpeg"},{"name":"Bay of Fundy","rarity":"rare","id":"bay-of-fundy","subtitle":"Bay","details":"Home to the world's highest tides, rising up to 16 metres at the head of the bay in Canada's Minas Basin.","image":"https://upload.wikimedia.org/wikipedia/commons/3/35/Bay_of_Fundy_at_Low_Tide.jpg"},{"name":"Gulf of St. Lawrence","rarity":"rare","id":"gulf-of-st-lawrence","subtitle":"Gulf","details":"Outlet of the St. Lawrence River and the Great Lakes to the Atlantic, bordered by Quebec, New Brunswick and Nova Scotia.","image":"https://upload.wikimedia.org/wikipedia/commons/d/db/Baie_Trinite_023.jpg"},{"name":"Gulf of Guinea","rarity":"rare","id":"gulf-of-guinea","subtitle":"Gulf","details":"Broad Atlantic bight off West Africa where the Equator crosses the Prime Meridian, south of Ghana and Nigeria.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c8/Pr%C3%ADncipe_Island_Biosphere_Reserve_-_Praia_Salgada.jpg"},{"name":"Gulf of Carpentaria","rarity":"rare","id":"gulf-of-carpentaria","subtitle":"Gulf","details":"Shallow gulf in northern Australia between Arnhem Land and Cape York Peninsula, famed for Morning Glory roll clouds.","image":"https://upload.wikimedia.org/wikipedia/commons/3/30/ISS-43_Eastern_Gulf_of_Carpentaria%2C_Queensland%2C_Australia.jpg"},{"name":"Gulf of Thailand","rarity":"rare","id":"gulf-of-thailand","subtitle":"Gulf","details":"Shallow arm of the South China Sea bordered by Thailand, Cambodia, Vietnam and Malaysia.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e1/Koh_Mak_%28island%29%2C_Thailand%2C_Yachting_in_the_Gulf_of_Thailand%2C_Blue_sea.jpg"},{"name":"Bab el-Mandeb","rarity":"rare","id":"bab-el-mandeb","subtitle":"Strait","details":"Strait joining the Red Sea to the Gulf of Aden between Yemen and Djibouti; its Arabic name means 'Gate of Tears'.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1f/Bab-el-Mandeb_And_Red_Sea_NASA_photo.webp"},{"name":"Taiwan Strait","rarity":"rare","id":"taiwan-strait","subtitle":"Strait","details":"Waterway between Taiwan and mainland China linking the South China Sea to the East China Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b8/%E5%BD%B0%E5%8C%96%E7%B8%A3%E8%8A%B3%E8%8B%91%E9%84%89_%E7%8E%8B%E5%8A%9F%E6%BC%81%E6%B8%AF_-_panoramio_%281%29.jpg"},{"name":"Korea Strait","rarity":"rare","id":"korea-strait","subtitle":"Strait","details":"Strait between South Korea and Japan linking the East China Sea to the Sea of Japan, split by Tsushima Island.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7d/Top-Mount-Shiroyama-and-Aso-Bay-Tsushima.jpg"},{"name":"Mozambique Channel","rarity":"rare","id":"mozambique-channel","subtitle":"Channel","details":"Channel between Madagascar and Mozambique about 1,600 km long, separating the island from mainland Africa.","image":"https://upload.wikimedia.org/wikipedia/commons/d/de/Evening._Mozambique_Channel_%2822154081854%29.jpg"},{"name":"Bass Strait","rarity":"rare","id":"bass-strait","subtitle":"Channel","details":"Rough strait between Tasmania and mainland Australia, named for explorer George Bass, who proved Tasmania was an island.","image":"https://upload.wikimedia.org/wikipedia/commons/6/67/Squeaky_Beach%2C_Wilsons_Promontory_National_Park.jpg"},{"name":"Amu Darya","rarity":"uncommon","id":"amu-darya","subtitle":"River","details":"Historically flowed to the Aral Sea; it forms much of Afghanistan's northern border with Tajikistan, Uzbekistan and Turkmenistan.","image":"https://upload.wikimedia.org/wikipedia/commons/9/96/Amudarya_by_Nukus%2C_Uzbekistan_%28%D0%90%D0%BC%D1%83%D0%B4%D0%B0%D1%80%D1%8C%D1%8F_%D1%80%D1%8F%D0%B4%D0%BE%D0%BC_%D0%B3%D0%BE%D1%80%D0%BE%D0%B4%D0%B0_%D0%9D%D1%83%D0%BA%D1%83%D1%81%29.jpg"},{"name":"Syr Darya","rarity":"uncommon","id":"syr-darya","subtitle":"River","details":"Central Asia's longest river, flowing from the Tian Shan through Kazakhstan to the North Aral Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ed/Syr_Darya.jpg"},{"name":"Ural River","rarity":"uncommon","id":"ural-river","subtitle":"River","details":"Traditionally marks part of the boundary between Europe and Asia as it flows south to the Caspian Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/3/31/Ural_river.jpg"},{"name":"Don River","rarity":"uncommon","id":"don-river","subtitle":"River","details":"Flows across southern Russia to the Sea of Azov and is linked to the Volga by a shipping canal.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ae/Don_%28Voronezh_Oblast%29.jpg"},{"name":"Vistula River","rarity":"uncommon","id":"vistula-river","subtitle":"River","details":"Poland's longest river, flowing north past Krakow and Warsaw to the Baltic Sea near Gdansk.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0b/Dolina-dolnej-wis%C5%82y.jpg"},{"name":"Oder River","rarity":"uncommon","id":"oder-river","subtitle":"River","details":"Forms much of the border between Poland and Germany before emptying into the Baltic Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/1/17/WyspaRedzinska-GK.JPG"},{"name":"Po River","rarity":"uncommon","id":"po-river","subtitle":"River","details":"Italy's longest river, flowing east across the Po Valley to a wide delta on the Adriatic Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/8/81/Torino_-_vista_ponte_Isabella_-_Castello_del_Valentino_e_Mole_Antonelliana.jpg"},{"name":"Ebro River","rarity":"uncommon","id":"ebro-river","subtitle":"River","details":"Flows across northern Spain to the Mediterranean, where its delta is famed for rice fields and flamingos.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ef/Zaragoza_shel.JPG"},{"name":"Douro River","rarity":"uncommon","id":"douro-river","subtitle":"River","details":"Famed for the terraced vineyards of Port wine country, it flows past Porto into the Atlantic Ocean.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4a/Rio_Douro_-_Portugal_%2832615481975%29_%28cropped%29.jpg"},{"name":"Rhône River","rarity":"uncommon","id":"rhone-river","subtitle":"River","details":"Rises in the Swiss Alps, passes through Lake Geneva and flows south across France to the Mediterranean Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/1/11/Vue_du_Rh%C3%B4ne_depuis_le_Pont_Wilson_%28Lyon%29%2C_mai_2019.jpg"},{"name":"Connecticut River","rarity":"uncommon","id":"connecticut-river","subtitle":"River","details":"New England's longest river, flowing 410 miles from the Canadian border south to Long Island Sound.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7e/Connecticut_River_From_Gillette_Castle.jpg"},{"name":"Susquehanna River","rarity":"uncommon","id":"susquehanna-river","subtitle":"River","details":"The longest river on the US East Coast, it supplies about half of the Chesapeake Bay's freshwater inflow.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f0/Asylum_Township.jpg"},{"name":"Delaware River","rarity":"uncommon","id":"delaware-river","subtitle":"River","details":"Its main stem flows free, without dams, forming state borders on its way to Delaware Bay.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e9/2021-06-16_09_10_03_View_of_the_Delaware_Water_Gap_from_the_Delaware_River_Viaduct_over_the_Delaware_River_on_the_border_of_Knowlton_Township%2C_Warren_County%2C_New_Jersey_and_Upper_Mount_Bethel_Township%2C_Northampton_County%2C_Pennsylvania.jpg"},{"name":"Potomac River","rarity":"uncommon","id":"potomac-river","subtitle":"River","details":"Flows past Washington, DC on its way to Chesapeake Bay and is often called the Nation's River.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0f/Great_Falls_of_the_Potomac_River_-_NPS.jpg"},{"name":"Tennessee River","rarity":"uncommon","id":"tennessee-river","subtitle":"River","details":"The Ohio River's longest tributary, looping through seven states and dammed by a chain of TVA lakes.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f0/Market_Street_Bridge_02.jpg"},{"name":"Cumberland River","rarity":"uncommon","id":"cumberland-river","subtitle":"River","details":"Flows through Nashville, Tennessee and Kentucky before joining the Ohio River.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a2/Cumberland_River_2005_05_20.jpeg"},{"name":"Wabash River","rarity":"uncommon","id":"wabash-river","subtitle":"River","details":"Indiana's defining river, flowing southwest across the state to join the Ohio River.","image":"https://upload.wikimedia.org/wikipedia/commons/2/21/Wabash_River.jpg"},{"name":"Illinois River","rarity":"uncommon","id":"illinois-river","subtitle":"River","details":"Links the Chicago area and Lake Michigan's waterways with the Mississippi River system.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9a/Illinois_River_near_LaSalle_Illinois.jpg"},{"name":"Brazos River","rarity":"uncommon","id":"brazos-river","subtitle":"River","details":"One of Texas's longest rivers, flowing southeast across the state to the Gulf of Mexico near Freeport.","image":"https://upload.wikimedia.org/wikipedia/commons/0/07/Brazos_River_below_Possum_Kingdom_Lake%2C_Palo_Pinto_County%2C_Texas.jpg"},{"name":"Pecos River","rarity":"uncommon","id":"pecos-river","subtitle":"River","details":"Flows from New Mexico across West Texas to join the Rio Grande near Del Rio.","image":"https://upload.wikimedia.org/wikipedia/commons/d/df/Pecos_river_bridge.jpg"},{"name":"Gila River","rarity":"uncommon","id":"gila-river","subtitle":"River","details":"A major Colorado River tributary that once flowed across southern Arizona from New Mexico to Yuma.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7c/Gila_box_nca.jpg"},{"name":"Sacramento River","rarity":"uncommon","id":"sacramento-river","subtitle":"River","details":"California's largest river by flow, running south through the Sacramento Valley to the Delta and San Francisco Bay.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3e/Sacramento_River.JPG"},{"name":"San Joaquin River","rarity":"uncommon","id":"san-joaquin-river","subtitle":"River","details":"Flows north up California's Central Valley to meet the Sacramento River in the Delta.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9f/San_Joaquin_River_at_Vernalis.jpg"},{"name":"Willamette River","rarity":"uncommon","id":"willamette-river","subtitle":"River","details":"Flows north through Eugene and Portland, Oregon before joining the Columbia River.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4d/USACE_Fremont_Bridge_Portland.jpg"},{"name":"Churchill River","rarity":"uncommon","id":"churchill-river","subtitle":"River","details":"Flows east across northern Manitoba to Hudson Bay near the town of Churchill, famed for polar bears.","image":"https://upload.wikimedia.org/wikipedia/commons/7/77/Otter_rapids.jpg"},{"name":"Nelson River","rarity":"uncommon","id":"nelson-river","subtitle":"River","details":"Drains Lake Winnipeg northeast across Manitoba, dropping steeply to Hudson Bay.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a8/Nelson_River_near_Norway_House%2C_from_the_air.jpg"},{"name":"Peace River","rarity":"uncommon","id":"peace-river","subtitle":"River","details":"Flows from British Columbia across Alberta to join the Athabasca and form the Slave River in the Mackenzie system.","image":"https://upload.wikimedia.org/wikipedia/commons/1/11/Peace_River_Valley_Site_C_Flooding_Area.jpg"},{"name":"Athabasca River","rarity":"uncommon","id":"athabasca-river","subtitle":"River","details":"Rises at the Columbia Icefield in Alberta and flows northeast to Lake Athabasca.","image":"https://upload.wikimedia.org/wikipedia/commons/7/77/Meltwater_at_the_terminus_of_the_Athabasca_Glacier%2C_Jasper_National_Park%2C_Alberta%2C_Canada.jpg"},{"name":"Liard River","rarity":"uncommon","id":"liard-river","subtitle":"River","details":"A major Mackenzie River tributary flowing through the Yukon, British Columbia and the Northwest Territories.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e9/Liard-River-Nahanni_Ranges.jpg"},{"name":"Madeira River","rarity":"uncommon","id":"madeira-river","subtitle":"River","details":"The Amazon's largest tributary by discharge, carrying sediment-rich whitewater down from the Bolivian Andes.","image":"https://upload.wikimedia.org/wikipedia/commons/0/05/Rio_Madeira_09072007.jpg"},{"name":"Rio Negro","rarity":"uncommon","id":"rio-negro","subtitle":"River","details":"The Amazon's largest left tributary and the world's largest blackwater river, its dark, tea-coloured waters meet the Amazon at Manaus.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9e/Ponte_Rio_Negro.jpg"},{"name":"Paraguay River","rarity":"uncommon","id":"paraguay-river","subtitle":"River","details":"Flows south through Brazil's vast Pantanal wetlands before joining the Parana River in Paraguay.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c4/CON_-_Paraguay_River_at_Concepcion%2C_Paraguay%2C_2023.jpg"},{"name":"Uruguay River","rarity":"uncommon","id":"uruguay-river","subtitle":"River","details":"Forms borders between Argentina, Brazil and Uruguay before joining the Parana to form the Rio de la Plata.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2b/Atardeceruruguayrio.JPG"},{"name":"Magdalena River","rarity":"uncommon","id":"magdalena-river","subtitle":"River","details":"Colombia's principal river, flowing north between Andean ranges to the Caribbean Sea near Barranquilla.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f2/Rio_Magdalena_Delta_landsat.jpg"},{"name":"Essequibo River","rarity":"uncommon","id":"essequibo-river","subtitle":"River","details":"Guyana's largest river, flowing north through rainforest and savanna to the Atlantic Ocean.","image":"https://upload.wikimedia.org/wikipedia/commons/4/48/Essequibo_River.jpg"},{"name":"Limpopo River","rarity":"uncommon","id":"limpopo-river","subtitle":"River","details":"Crosses southern Africa, forming stretches of South Africa's northern border before reaching the Indian Ocean in Mozambique.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c9/Limpopo.jpg"},{"name":"Senegal River","rarity":"uncommon","id":"senegal-river","subtitle":"River","details":"Forms much of the border between Senegal and Mauritania as it flows west to the Atlantic at Saint-Louis.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c9/WL-S%C3%A9n%C3%A9gal-Rosso-Travers%C3%A9e_du_fleuve_S%C3%A9n%C3%A9gal.jpg"},{"name":"Volta River","rarity":"uncommon","id":"volta-river","subtitle":"River","details":"Flows south through Ghana to Lake Volta and the Gulf of Guinea, its basin covering most of the country.","image":"https://upload.wikimedia.org/wikipedia/commons/7/71/VoltaRiverWithAdombeBridge183-1-.jpg"},{"name":"Ubangi River","rarity":"uncommon","id":"ubangi-river","subtitle":"River","details":"The Congo River's largest right-bank tributary, forming borders of the Central African Republic and DR Congo.","image":"https://upload.wikimedia.org/wikipedia/commons/5/5a/Ubangi_river_near_Bangui.jpg"},{"name":"Kasai River","rarity":"uncommon","id":"kasai-river","subtitle":"River","details":"A major Congo tributary flowing from Angola across DR Congo, long known for its diamond-rich basin.","image":"https://upload.wikimedia.org/wikipedia/commons/d/df/Sunset_view_from_Kalonda.jpg"},{"name":"Blue Nile","rarity":"uncommon","id":"blue-nile","subtitle":"River","details":"Rises at Ethiopia's Lake Tana and brings most of the Nile's floodwater and fertile silt to Khartoum.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0b/ET_Bahir_Dar_asv2018-02_img32_view_from_Bezawit.jpg"},{"name":"White Nile","rarity":"uncommon","id":"white-nile","subtitle":"River","details":"Flows north from the Lake Victoria region through South Sudan to meet the Blue Nile at Khartoum.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9c/Sudan_Juba_bridge.jpg"},{"name":"Chao Phraya River","rarity":"uncommon","id":"chao-phraya-river","subtitle":"River","details":"Thailand's main river, formed by the Ping and Nan rivers and flowing through Bangkok to the Gulf of Thailand.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a5/Chao_Phraya_River_-_Bangkok_-_northwards_-_from_King_Taksin_Bridge_-_2021.jpg"},{"name":"Hong River","rarity":"uncommon","id":"hong-river","subtitle":"River","details":"Known as the Red River for its silt-laden waters, it flows from Yunnan through Hanoi to the Gulf of Tonkin.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b0/Vietnam%2C_Hanoi%2C_Panoramic_view_of_Red_River.jpg"},{"name":"Godavari River","rarity":"uncommon","id":"godavari-river","subtitle":"River","details":"Peninsular India's largest river, often called the Dakshin Ganga, flowing east to the Bay of Bengal.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d0/Nwgbridge.JPG"},{"name":"Krishna River","rarity":"uncommon","id":"krishna-river","subtitle":"River","details":"Flows east across India's Deccan Plateau through four states to the Bay of Bengal.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f9/Back_Water_View.jpg"},{"name":"Han River","rarity":"uncommon","id":"han-river","subtitle":"River","details":"The Yangtze River's longest tributary, joining it at Wuhan after flowing through Shaanxi and Hubei.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4d/Hanshui_River_in_Wuhan_-_panoramio.jpg"},{"name":"Huai River","rarity":"uncommon","id":"huai-river","subtitle":"River","details":"A major river of eastern China flowing between the Yellow River and Yangtze basins.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d6/201806_Bengbu_and_Huai_River.jpg"},{"name":"Lake Peipus","rarity":"uncommon","id":"lake-peipus","subtitle":"Lake","details":"Europe's fifth-largest lake, on the Estonia-Russia border; its frozen surface hosted the famous Battle on the Ice in 1242.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3e/Lake_Peipus%2C_LandSat-8%2C_2016-10-20.jpg"},{"name":"Lake Vänern","rarity":"uncommon","id":"lake-vanern","subtitle":"Lake","details":"The largest lake in Sweden and in the European Union, and the third-largest lake in Europe.","image":"https://upload.wikimedia.org/wikipedia/commons/2/20/H%C3%A4llekis_industrier_sedda_fr_utsiktstornet_p%C3%A5_Kinnekulle_6116.jpg"},{"name":"Lake Vättern","rarity":"uncommon","id":"lake-vattern","subtitle":"Lake","details":"Sweden's second-largest lake, a long, deep, exceptionally clear lake reaching 128 metres deep.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c4/A_distant_memory_%282835767026%29.jpg"},{"name":"Lake Saimaa","rarity":"uncommon","id":"lake-saimaa","subtitle":"Lake","details":"Finland's largest lake, a labyrinth of channels and islands home to the Saimaa ringed seal, found nowhere else.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fd/Lake_Saimaa_aerial.jpg"},{"name":"Lake Balaton","rarity":"uncommon","id":"lake-balaton","subtitle":"Lake","details":"Central Europe's largest lake, nicknamed the Hungarian Sea, yet averaging only about 3 metres deep.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9e/Balaton_Hungary_Landscape.jpg"},{"name":"Lake Garda","rarity":"uncommon","id":"lake-garda","subtitle":"Lake","details":"Italy's largest lake, carved by glaciers between the Alps and the Po plain, with the Sarca flowing in and the Mincio out.","image":"https://upload.wikimedia.org/wikipedia/commons/2/24/La_Rocca_di_Manerba_del_Garda_con_l%27isola_dei_Conigli.jpg"},{"name":"Lake Constance","rarity":"uncommon","id":"lake-constance","subtitle":"Lake","details":"Bordered by Germany, Austria and Switzerland, with the Rhine flowing in at the east end and out at the west.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cc/Lake_Constance_Edited.png"},{"name":"Lake Maggiore","rarity":"uncommon","id":"lake-maggiore","subtitle":"Lake","details":"Italy's second-largest lake after Garda, stretching into Switzerland, with the Borromean Islands and the Ticino River flowing through it.","image":"https://upload.wikimedia.org/wikipedia/commons/3/39/LagoMaggiore.jpg"},{"name":"Lake Ohrid","rarity":"uncommon","id":"lake-ohrid","subtitle":"Lake","details":"One of Europe's oldest and deepest lakes, formed millions of years ago and home to more than 200 species found nowhere else on Earth.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f0/Lake_Ohrid%2C_Macedonia-Albania_viewed_from_a_NASA_satellite.jpg"},{"name":"Lake Tana","rarity":"uncommon","id":"lake-tana","subtitle":"Lake","details":"Ethiopia's largest lake and the source of the Blue Nile, which leaves its southern shore near Bahir Dar toward Sudan and Egypt.","image":"https://upload.wikimedia.org/wikipedia/commons/8/84/Lake_tana.jpg"},{"name":"Lake Albert","rarity":"uncommon","id":"lake-albert","subtitle":"Lake","details":"An African Great Lake on the Uganda–DR Congo border; the Nile enters at its north end and leaves as the Albert Nile.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b4/Lake_albert_in_hoima.jpg"},{"name":"Lake Edward","rarity":"uncommon","id":"lake-edward","subtitle":"Lake","details":"The smallest of the African Great Lakes, in the Rift Valley on the Uganda–DR Congo border, linked to Lake George by the Kazinga Channel.","image":"https://upload.wikimedia.org/wikipedia/commons/0/00/Lake_edward_sentinel-2.jpg"},{"name":"Lake Kivu","rarity":"uncommon","id":"lake-kivu","subtitle":"Lake","details":"One of only three known exploding lakes: its deep water traps vast dissolved carbon dioxide and methane, some drawn off to generate power.","image":"https://upload.wikimedia.org/wikipedia/commons/1/19/LakeKivu_satellite.jpg"},{"name":"Lake Eyre","rarity":"uncommon","id":"lake-eyre","subtitle":"Lake","details":"Mostly a dry salt pan 15 m below sea level — Australia's lowest point — it becomes the country's largest lake only in rare, major floods.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c6/NEO_lake_eyre_big.jpg"},{"name":"Lake Wakatipu","rarity":"uncommon","id":"lake-wakatipu","subtitle":"Lake","details":"New Zealand's longest lake, at 80 km; a seiche makes its level rise and fall in a slow rhythm of about 27 minutes in Queenstown Bay.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d7/LakeWakatipuNov172024_02.jpg"},{"name":"Lake Biwa","rarity":"uncommon","id":"lake-biwa","subtitle":"Lake","details":"Japan's largest freshwater lake and one of the world's ancient lakes, formed about 4 million years ago in Shiga Prefecture near Kyoto.","image":"https://upload.wikimedia.org/wikipedia/commons/d/df/Lake_biwa.jpg"},{"name":"Lake Khovsgol","rarity":"uncommon","id":"lake-khovsgol","subtitle":"Lake","details":"Mongolia's largest freshwater lake by volume, a deep rift lake nicknamed Baikal's younger sister, draining eventually toward Lake Baikal.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d9/ISS067-E-879_-_View_of_Earth.jpg"},{"name":"Lake Sevan","rarity":"uncommon","id":"lake-sevan","subtitle":"Lake","details":"Armenia's largest lake, sitting about 1,900 m above sea level in the Caucasus, fed by many rivers and drained by the Hrazdan River.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a2/Lake_Sevan_2022-08-14_Sentinel-2_L2A.jpg"},{"name":"Lake Urmia","rarity":"uncommon","id":"lake-urmia","subtitle":"Lake","details":"A vast hypersaline lake in northwestern Iran, once dotted with islands and famed for brine shrimp and flocks of migrating flamingos.","image":"https://upload.wikimedia.org/wikipedia/commons/8/88/Lake_urmia_1984.jpg"},{"name":"Lake Poyang","rarity":"uncommon","id":"lake-poyang","subtitle":"Lake","details":"China's largest freshwater lake swells and shrinks with the seasons, and its winter wetlands host most of the world's Siberian cranes.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4b/Satelites_image_of_Lake_Poyang.png"},{"name":"Lake Khanka","rarity":"uncommon","id":"lake-khanka","subtitle":"Lake","details":"A shallow transboundary lake shared by China and Russia, ringed by protected wetlands rich in cranes, storks and other waterbirds.","image":"https://upload.wikimedia.org/wikipedia/commons/d/da/Lake_Khanka_Landsat_7_2001-09-25.jpg"},{"name":"Reindeer Lake","rarity":"uncommon","id":"reindeer-lake","subtitle":"Lake","details":"A deep, island-dotted Canadian lake on the Saskatchewan–Manitoba border, draining north into Hudson Bay through the Reindeer River.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b5/Canada.A2002236.1810.721.250m_NASA.jpg"},{"name":"Nettilling Lake","rarity":"uncommon","id":"nettilling-lake","subtitle":"Lake","details":"The world's largest lake on an island: 5,542 km² on Baffin Island, crossed by the Arctic Circle and frozen for most of the year.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c6/Nettilling_Lake_2019-08-21_Sentinel-2_L2A_Highlight_Optimized_Natural_Color.jpg"},{"name":"Lake Winnipegosis","rarity":"uncommon","id":"lake-winnipegosis","subtitle":"Lake","details":"The second-largest of central Manitoba's three great lakes, all remnants of glacial Lake Agassiz; its name means 'little muddy waters'.","image":"https://upload.wikimedia.org/wikipedia/commons/6/62/WinnipegosisBeach.JPG"},{"name":"Lake Manitoba","rarity":"uncommon","id":"lake-manitoba","subtitle":"Lake","details":"A shallow lake in Manitoba, only about 7 m at its deepest, split into north and south basins by The Narrows, a remnant of Lake Agassiz.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3c/Delta_Beach_Manitoba_Canada.JPG"},{"name":"Lake St. Clair","rarity":"uncommon","id":"lake-st-clair","subtitle":"Lake","details":"A small, shallow lake between Huron and Erie — not an official Great Lake, but a link in their chain via the St. Clair and Detroit rivers.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6f/Lake_St_Clair_by_Sentinel-2_2022-08-13.jpg"},{"name":"Lake Champlain","rarity":"uncommon","id":"lake-champlain","subtitle":"Lake","details":"For 18 days in 1998, a U.S. law declared this Vermont–New York lake the sixth Great Lake, before Congress removed the title.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a6/Lake_Champlain_Valley.jpg"},{"name":"Lake Okeechobee","rarity":"uncommon","id":"lake-okeechobee","subtitle":"Lake","details":"Florida's 'Inland Sea' is its largest freshwater lake, covering 730 sq mi yet averaging only about 9 ft deep, and feeds the Everglades.","image":"https://upload.wikimedia.org/wikipedia/commons/3/35/Florida_Lac_Okeechobee.jpg"},{"name":"Kara Sea","rarity":"uncommon","id":"kara-sea","subtitle":"Sea","details":"A cold Arctic sea off Siberia that receives the Ob and Yenisei rivers and stays ice-covered for much of the year on the Northern Sea Route.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b6/2018-10-01_MODIS_Terra_Kara_Sea_cyclone_between_Novaya_Zemlya_and_Siberia_970_hPa.jpg"},{"name":"Laptev Sea","rarity":"uncommon","id":"laptev-sea","subtitle":"Sea","details":"An Arctic sea off Siberia named for Laptev explorers, where the Lena River builds a vast delta and winter sea ice forms in great quantity.","image":"https://upload.wikimedia.org/wikipedia/commons/1/18/Laptev_sea_sunset.JPG"},{"name":"East Siberian Sea","rarity":"uncommon","id":"east-siberian-sea","subtitle":"Sea","details":"One of the least-studied Arctic seas, a vast, shallow shelf sea off northeastern Siberia that is ice-covered for most of the year.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e6/East_Siberia_Sea.jpg"},{"name":"White Sea","rarity":"uncommon","id":"white-sea","subtitle":"Sea","details":"A southern inlet of the Barents Sea in northwestern Russia, linked by canal toward the Baltic and home to the port of Arkhangelsk.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9c/Islands_in_the_White_sea.jpg"},{"name":"Celebes Sea","rarity":"uncommon","id":"celebes-sea","subtitle":"Sea","details":"Also called the Sulawesi Sea, a deep basin south of the Philippines reaching about 6,200 m, among the deepest waters in Indonesia.","image":"https://upload.wikimedia.org/wikipedia/commons/c/ca/Aerial_Panorama_of_Pulau_Bangka_in_North_Sulawesi_Indonesia.jpg"},{"name":"Sulu Sea","rarity":"uncommon","id":"sulu-sea","subtitle":"Sea","details":"A deep sea between the Philippines and Borneo, enclosing the Tubbataha Reefs, a UNESCO-listed marine park famed for sharks and turtles.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e7/Sulu_Sea_internal_waves.jpg"},{"name":"Flores Sea","rarity":"uncommon","id":"flores-sea","subtitle":"Sea","details":"An Indonesian sea lying north of Flores and south of Sulawesi, covering deep basins between the Java Sea and the Banda Sea.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fd/Dusk_%26_Dawn_in_Kalong_Island%2C_Labuan_Bajo.jpg"},{"name":"Timor Sea","rarity":"uncommon","id":"timor-sea","subtitle":"Sea","details":"A shallow sea between Timor and northwestern Australia, lying over rich offshore oil and gas fields beneath the Sahul Shelf.","image":"https://upload.wikimedia.org/wikipedia/commons/4/45/Tasiibun.jpg"},{"name":"Ligurian Sea","rarity":"uncommon","id":"ligurian-sea","subtitle":"Sea","details":"The arm of the Mediterranean along the Italian Riviera and Corsica, protected in part as the Pelagos Sanctuary for whales and dolphins.","image":"https://upload.wikimedia.org/wikipedia/commons/d/dd/Ligurian_Sea_near_Portofino_%281%29.jpg"},{"name":"Tyrrhenian Sea","rarity":"uncommon","id":"tyrrhenian-sea","subtitle":"Sea","details":"The sea off Italy's west coast, enclosed by Sardinia, Corsica, Sicily and the mainland, with volcanic islands including Stromboli.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d8/Sunset_in_the_Tyrrhenian_Sea_-_panoramio.jpg"},{"name":"Adriatic Sea","rarity":"uncommon","id":"adriatic-sea","subtitle":"Sea","details":"A long, narrow arm of the Mediterranean between Italy and the Balkans, shallow in the north, with Venice at its head.","image":"https://upload.wikimedia.org/wikipedia/commons/4/49/Adriatic_Sea_2003.jpg"},{"name":"Ionian Sea","rarity":"uncommon","id":"ionian-sea","subtitle":"Sea","details":"Home to Calypso Deep, the Mediterranean's deepest point at over 5,000 m below the surface, southwest of the Peloponnese in Greece.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1c/Aerial_view_of_Zakynthos_%28Greece%29_-_Aeris_Beach.jpg"},{"name":"Aegean Sea","rarity":"uncommon","id":"aegean-sea","subtitle":"Sea","details":"An embayed sea between Greece and Türkiye scattered with islands — Crete marks its southern edge and the Cyclades crowd its centre.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fa/Aegean_sea_Kolymbia.jpg"},{"name":"Sea of Marmara","rarity":"uncommon","id":"sea-of-marmara","subtitle":"Sea","details":"Türkiye's inland sea, joining the Black Sea to the Aegean through the Bosphorus and Dardanelles, with Istanbul on its shore.","image":"https://upload.wikimedia.org/wikipedia/commons/6/66/Istanbul_beaches-_Sea_of_Marmara_-_Tourism_in_Turkey_07.jpg"},{"name":"Sea of Azov","rarity":"uncommon","id":"sea-of-azov","subtitle":"Sea","details":"The world's shallowest sea, averaging only about 7 m deep and never more than 14 m, fed by the Don and Kuban rivers.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2b/Azow_Sea_Sunset.JPG"},{"name":"Bismarck Sea","rarity":"uncommon","id":"bismarck-sea","subtitle":"Sea","details":"A sea northeast of Papua New Guinea in the Bismarck Archipelago, site of a major Allied air victory over a Japanese convoy in 1943.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1a/Manam_Volcano.jpg"},{"name":"Salish Sea","rarity":"uncommon","id":"salish-sea","subtitle":"Sea","details":"A shared Canada–U.S. inland sea uniting Puget Sound, the Strait of Georgia and Juan de Fuca, its name honouring Coast Salish peoples.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7c/Vancouver_Island_by_Aqua%2C_2020-07-26_%28cropped_to_Salish_Sea%29.jpg"},{"name":"San Francisco Bay","rarity":"uncommon","id":"san-francisco-bay","subtitle":"Bay","details":"California's great estuary, where the Sacramento and San Joaquin rivers meet Pacific tides through the narrow Golden Gate.","image":"https://upload.wikimedia.org/wikipedia/commons/6/60/Bay_Area_by_Sentinel-2%2C_2019-03-11_%28small_version%29.jpg"},{"name":"Baffin Bay","rarity":"uncommon","id":"baffin-bay","subtitle":"Bay","details":"A sea between Canada's Baffin Island and Greenland, linking the Arctic Ocean to the Atlantic and serving as a winter home for narwhals.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c5/Buiobuione_-_Artic_Scenic_view_of_Greenland_icebergs_in_Baffin_Bay_in_Disko_Bay_06.jpg"},{"name":"James Bay","rarity":"uncommon","id":"james-bay","subtitle":"Bay","details":"The shallow southern arm of Hudson Bay, fed by major Quebec rivers including the La Grande and Eastmain, long used by Cree communities.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ac/James_bay_in_summer.jpg"},{"name":"Bristol Bay","rarity":"uncommon","id":"bristol-bay","subtitle":"Bay","details":"An arm of the Bering Sea in southwestern Alaska that supports the world's largest sockeye salmon fishery.","image":"https://upload.wikimedia.org/wikipedia/commons/4/45/Bristol_Bay_shore.jpg"},{"name":"Gulf of Aden","rarity":"uncommon","id":"gulf-of-aden","subtitle":"Gulf","details":"Between Yemen and the Horn of Africa, this gulf links the Red Sea at Bab el-Mandeb to the Arabian Sea on a busy shipping route.","image":"https://upload.wikimedia.org/wikipedia/commons/7/70/Envisat_image_of_the_Gulf_of_Aden_ESA219526.jpg"},{"name":"Gulf of Oman","rarity":"uncommon","id":"gulf-of-oman","subtitle":"Gulf","details":"Connects the Arabian Sea to the Persian Gulf through the Strait of Hormuz, off the coasts of Oman, Iran and the Emirates.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3c/Dhow_trip_in_the_fjords_of_Musandam%2C_Oman_%2836208084624%29.jpg"},{"name":"Gulf of Finland","rarity":"uncommon","id":"gulf-of-finland","subtitle":"Gulf","details":"The eastern arm of the Baltic Sea, reaching St. Petersburg at its head and freezing over in winter between Finland and Estonia.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ef/Frozen_Gulf_of_Finland_as_seen_from_Uutela%2C_Vuosaari%2C_Helsinki%2C_Finland%2C_2018_February.jpg"},{"name":"Gulf of Bothnia","rarity":"uncommon","id":"gulf-of-bothnia","subtitle":"Gulf","details":"The northern arm of the Baltic between Sweden and Finland, with such low salinity that many freshwater fish species live in it.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e3/Lighthouse_on_an_island_on_Sweden%27s_portion_of_the_Gulf_of_Bothnia_%2853473384942%29.jpg"},{"name":"Gulf of Riga","rarity":"uncommon","id":"gulf-of-riga","subtitle":"Gulf","details":"A Baltic gulf between Latvia and Estonia, fed by the Daugava River and partly closed off by the islands of Saaremaa and Hiiumaa.","image":"https://upload.wikimedia.org/wikipedia/commons/2/24/20150507_14_Jurmala_-_Gulf_of_Riga_%2817431199606%29.jpg"},{"name":"Norton Sound","rarity":"uncommon","id":"norton-sound","subtitle":"Sound","details":"A Bering Sea inlet in western Alaska south of the Seward Peninsula; Nome, the Iditarod's finish line, sits on its northern shore.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9b/Bering_Sea_Storm%2C_Looking_Down_East_Beach_%285188618614%29.jpg"},{"name":"Dardanelles","rarity":"uncommon","id":"dardanelles","subtitle":"Strait","details":"The narrow Turkish strait — the ancient Hellespont — linking the Aegean Sea to the Sea of Marmara, with Gallipoli on its western shore.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a2/Container_Ship_South_of_1915_%C3%87anakkale_Bridge%2C_Dardanelles_Strait%2C_2024.jpg"},{"name":"Cook Strait","rarity":"uncommon","id":"cook-strait","subtitle":"Strait","details":"New Zealand's strait between the North and South Islands, notorious for fierce winds and strong tidal currents funnelled between them.","image":"https://upload.wikimedia.org/wikipedia/commons/3/35/Earth_from_Space-_Cook_Strait%2C_New_Zealand_ESA24912671.jpg"},{"name":"Torres Strait","rarity":"uncommon","id":"torres-strait","subtitle":"Strait","details":"A shallow strait between Australia and New Guinea, dotted with more than 200 islands and dangerous coral reefs and shoals for ships.","image":"https://upload.wikimedia.org/wikipedia/commons/7/70/Thursday_Island%2C_Torres_Strait.jpg"},{"name":"Sunda Strait","rarity":"uncommon","id":"sunda-strait","subtitle":"Strait","details":"Between Java and Sumatra, this Indonesian strait joins the Java Sea to the Indian Ocean and holds the volcanic Krakatoa islands.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a4/Indahnya_Pemandangan_Selat_Sunda-10.jpg"},{"name":"Davis Strait","rarity":"uncommon","id":"davis-strait","subtitle":"Strait","details":"A broad strait between Greenland and Canada's Baffin Island, connecting Baffin Bay with the Labrador Sea and carrying ice southward.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e4/Davis_Strait_Icebergs.jpg"},{"name":"Palk Strait","rarity":"uncommon","id":"palk-strait","subtitle":"Strait","details":"A shallow strait between India and Sri Lanka, named for governor Robert Palk, just north of the Adam's Bridge shoal chain.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a4/Pamban_Railway_Bridge_accros_Palk_Strait.jpg"},{"name":"Straits of Florida","rarity":"uncommon","id":"straits-of-florida","subtitle":"Strait","details":"Between Florida and Cuba, these straits carry the powerful Florida Current — the start of the Gulf Stream — from the Gulf into the Atlantic.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f1/Straits_of_florida.png"}]});
